import {createServer} from 'node:http'
import {connect} from 'node:net'
export const names=['http_proxy','HTTP_PROXY','https_proxy','HTTPS_PROXY','no_proxy','NO_PROXY','all_proxy','ALL_PROXY','NODE_USE_ENV_PROXY']
export const environment=values=>({get:name=>values[name]===undefined?undefined:{value:values[name],source:'process'}})
export async function fakeEnvironment(values,fn){const saved=new Map(names.map(n=>[n,process.env[n]]));try{for(const n of names)delete process.env[n];Object.assign(process.env,values);return await fn(environment(values))}finally{for(const[n,value]of saved)if(value===undefined)delete process.env[n];else process.env[n]=value}}
export async function proxyFixture(t,{hold=false}={}){const entered=Promise.withResolvers(),release=Promise.withResolvers(),sockets=new Set(),seen=[];const origin=createServer(async(req,res)=>{entered.resolve();if(hold)await release.promise;res.writeHead(200,{'content-type':'text/plain'});res.end('NATIVE_PROXY_BODY_MARKER')});await new Promise(r=>origin.listen(0,'127.0.0.1',r));const proxy=createServer();proxy.on('connect',(req,client,head)=>{seen.push({target:req.url,auth:req.headers['proxy-authorization']});if(req.url!=='proxy-fixture.example:80'){client.destroy();return}const upstream=connect(origin.address().port,'127.0.0.1',()=>{client.write('HTTP/1.1 200 Connection Established\r\n\r\n');if(head.length)upstream.write(head);client.pipe(upstream);upstream.pipe(client)});sockets.add(upstream);upstream.on('close',()=>sockets.delete(upstream));upstream.on('error',()=>client.destroy());client.on('error',()=>upstream.destroy());client.on('close',()=>upstream.destroy())});for(const server of [origin,proxy])server.on('connection',s=>{sockets.add(s);s.on('close',()=>sockets.delete(s))});await new Promise(r=>proxy.listen(0,'127.0.0.1',r));t.after(async()=>{release.resolve();for(const socket of sockets)socket.destroy();await Promise.all([origin,proxy].map(s=>new Promise(r=>s.close(r))))});return{entered,release,seen,proxyURL:`http://fixture:password@127.0.0.1:${proxy.address().port}`,origin}}
